// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // Fuzz parameters: an address to act as caller and a uint256 to control block timestamp.
    // We will attempt two fallback calls from the same caller in the same block/time to see
    // that the correct contract reverts on the second call while the mutant accepts it.
    function testFuzz_property(address caller, uint256 ts) public {
        // Keep caller as a regular funded address so it can send 10 ether.
        vm.assume(caller != address(0));
        uint256 amount = 10 ether;
        vm.deal(caller, amount * 2);

        // Bound timestamp to reasonable range (but wide): between 1 and 1e12
        ts = bound(ts, 1, 1e12);

        // warp to chosen timestamp
        vm.warp(ts);

        // First call: should succeed when sending exactly 10 ether
        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: amount}("");
        // The correct contract expects the first call to succeed (it was funded in ctor)
        // if it reverted here something else is wrong with inputs; drop those cases
        vm.assume(ok1 == true);

        // Now attempt a second call within the same block / same timestamp
        vm.prank(caller);
        bool ok2;
        (ok2, ) = address(c).call{value: amount}("");

        // GENERAL RULE asserted: The reference implementation never permits two successful
        // fallback calls in the same block/time from the same caller with 10 ether each;
        // i.e., the second call must revert (ok2 == false) for the reference, while the
        // mutant that removed the time-order check will allow ok2 == true for some inputs.
        assertTrue(ok2 == false);
    }
}
